<template><article class="draft-card"><span class="draft-label">{{ sent?'已发送到私人聊天':'私信草稿 · 尚未发送' }}</span><h3>发送给 {{ draft.recipientName }}</h3><p class="draft-house">关于：{{ draft.houseTitle }}</p><label>确认消息全文<textarea v-model="content" maxlength="2000" rows="4" :disabled="sending || sent" /></label><p v-if="error" class="draft-error" role="alert">{{ error }}</p><p v-if="sent" class="draft-sent" role="status">✓ 已发送到私人聊天</p><div class="draft-actions"><button v-if="!sent" type="button" :disabled="sending || !content.trim()" @click="send">{{ sending?'正在发送…':'确认发送' }}</button><RouterLink :to="{path:'/app/messages',query:{conversation:draft.conversationId}}">查看聊天 →</RouterLink><button v-if="!sent" class="cancel" type="button" :disabled="sending" @click="cancel">取消</button></div></article></template>
<script setup>
import {ref} from 'vue'
import {messagesApi} from '../api/messages'
const props=defineProps({draft:{type:Object,required:true}}),emit=defineEmits(['sent','cancel'])
const content=ref(props.draft.content),sending=ref(false),sent=ref(!!props.draft.sent),error=ref('')
async function send(){if(sending.value||sent.value)return;sending.value=true;error.value='';try{const r=await messagesApi.confirm(props.draft.id,content.value);sent.value=true;emit('sent',r.data.conversationId)}catch(e){error.value=e.message||'发送失败，请重试'}finally{sending.value=false}}
async function cancel(){sending.value=true;try{await messagesApi.cancel(props.draft.id);emit('cancel',props.draft.id)}catch(e){error.value=e.message||'取消失败，请重试'}finally{sending.value=false}}
</script>
<style scoped>
.draft-card{background:#f0f6ed;border:1px solid #cbdcc8;border-radius:8px;padding:20px;color:#21483d;max-width:640px}.draft-label{font-size:11px;color:#5f8069}.draft-card h3{font-size:17px;margin:8px 0}.draft-house{font-size:12px;color:#6b7f70;margin-bottom:16px}.draft-card label{display:block;font-size:12px}.draft-card textarea{display:block;width:100%;margin:8px 0 14px;border:1px solid #cbdcc8;border-radius:5px;padding:12px;font:inherit;line-height:1.9;background:#fffefa;resize:vertical;color:#21483d}.draft-actions{display:flex;gap:18px;align-items:center;flex-wrap:wrap;font-size:12px}.draft-actions button{border:0;border-radius:4px;background:#168b78;color:white;padding:9px 15px;cursor:pointer;font:inherit}.draft-actions a{color:#168b78}.draft-actions button.cancel{background:none;color:#748574;padding:8px 0}.draft-actions button:disabled{opacity:.5;cursor:default}.draft-error{font-size:12px;color:#aa4536;margin-bottom:12px}.draft-sent{font-size:12px;color:#168b78;margin-bottom:12px}
</style>
